#pragma once

// How the kernel reaches Apple Music's XAML windows and their interface thread. Compiled only with AMPIFY_WITH_XAML
// (C++/WinRT projection of the Windows App SDK, generated by the MSVC job). Not run yet in Apple Music: the bench case
// 63-ui-surfaces checks the log lines written here.
//
// Window::Current() is null in a WinUI 3 desktop app. Apple Music keeps its windows as "app properties" of
// AMP.Utils.dll; its export SharedUtils::GetAppProperty gives them by name. Way found by AMExclusive (MIT,
// https://github.com/AntiOblivionis/AMExclusive, mod/src/UiAdapter.cpp:315-364 at 91f589d), adapted here.

#if defined(AMPIFY_WITH_XAML)

#include <windows.h>
#ifdef GetCurrentTime
#undef GetCurrentTime  // windows.h macro that breaks Storyboard::GetCurrentTime in the projection
#endif

#include <cstdint>
#include <string>
#include <string_view>

#include <winrt/Windows.Foundation.h>
#include <winrt/Microsoft.UI.Dispatching.h>
#include <winrt/Microsoft.UI.Xaml.h>

#include "../core/journal.hpp"

namespace ampify::win {

// The decorated name of `winrt::Windows::Foundation::IInspectable __cdecl SharedUtils::GetAppProperty(winrt::hstring
// const&)` in AMP.Utils.dll (x64 MSVC).
inline constexpr char kGetAppPropertyExport[] =
    "?GetAppProperty@SharedUtils@@YA?AUIInspectable@Foundation@Windows@winrt@@AEBUhstring@5@@Z";

// The window that Apple Music keeps under `property` ("MainWindow" or "MiniPlayerWindow"), or null: AMP.Utils.dll not
// loaded yet, export missing (another build of Apple Music), property absent (MiniPlayerWindow throws E_BOUNDS while
// the mini player is closed), or not a Window. Any thread. Never throws.
winrt::Microsoft::UI::Xaml::Window AppWindow(std::wstring_view property) noexcept;

// True once AMP.Utils.dll is loaded and exports GetAppProperty.
bool AppPropertyAvailable() noexcept;

// Makes the calling thread a member of the multithreaded apartment, for WinRT calls from the kernel's threads.
// A thread already in an apartment keeps it.
void EnsureMta() noexcept;

// Installs the DispatcherQueue backend of the interface-thread facade (ui_thread.hpp): AttachUiThread takes the main
// window from AppWindow("MainWindow"), PostToUiThread runs the work through its DispatcherQueue at Low priority,
// inside try/catch. Writes the log lines "Interface: main window obtained ..." and "Interface: first
// work run by the main window's DispatcherQueue ...". Call once, before AttachUiThread.
void InstallXamlUiThread(Journal& journal);

// The number of tasks the DispatcherQueue backend ran, for the log.
std::uint64_t XamlUiTasksRun() noexcept;

// Milliseconds since boot, for the refresh tickets.
std::uint64_t NowMs() noexcept;

// Text of an hresult as 0x8000FFFF, for the log.
std::string HresultText(std::int32_t code);

}  // namespace ampify::win

#endif  // AMPIFY_WITH_XAML
